{# skeleton_overlay.html — superposition de squelette partagée au niveau de la page.
   Utilisation (à l'intérieur d'un conteneur de contenu `position: relative`) :
     {% from "partials/skeleton_overlay.html" import skeleton_overlay %}
     {{ squelette_overlay(
          'mon-squelette',
          stat_cards=6,
          sections=[5, 4],
          contrôles = 3,
          tables=[{ 'cols' : [30, 15, 12, 15, 12], 'lignes' : 4 }]
       ) }}
   Paramètres :
     id — identifiant de l'élément, utilisé par hideSkeleton(id) dans main.js
     stat_cards — nombre de cases de cartes statistiques (par défaut 0)
     sections - liste du nombre de lignes, une entrée par bloc de section
     contrôles - nombre de bandes de rangées à bascule (par défaut 0)
     tables — liste de { 'cols': [widths], 'rows': n } pour refléter les vraies tables
     lignes — nombre de lignes par défaut lorsqu'une table omet les « lignes »
   Le fondu sortant est géré par l'assistant JS partagé : hideSkeleton('my-skeleton');
#}
{% macro skeleton_overlay(id, header=1, title_bar=0, stat_cards=0, sections=[], controls=0, tables=[], rows=3, cards=0) %}
